/**
 * NEW HIERARCHICAL STRUCTURE
 * Courses now use lecture groups instead of flat combined sections
 */
export interface LectureGroup {
    section: Section;                 // The lecture section itself
    compatibleDiscussions: Section[]; // Discussions that work with this lecture
    compatibleLabs: Section[];        // Labs that work with this lecture
}

export interface Course {
    id: string;
    number: string;
    name: string;
    description: string;
    department: Department;
    lectures?: LectureGroup[];
    standaloneLabs?: Section[];
    minCredits: number;
    maxCredits: number;
}

export interface Department {
    abbreviation: string;
    name: string;
    courses: Course[];
}

export interface Section {
    crn: number;
    number: string;
    seats: number;
    seatsAvailable: number;
    actualWaitlist: number;
    maxWaitlist: number;
    note?: string;
    description: string;
    term: string;
    computedTerm: string; // Computed academic term letter (A, B, C, D)
    is_interest_list?: boolean; // True for interest list placeholder sections
    periods: Period[];
}

export interface Period {
    type: string;
    professor: string;
    professorEmail?: string;
    startTime: Time;
    endTime: Time;
    location: string;
    building: string;
    room: string;
    seats: number;
    seatsAvailable: number;
    actualWaitlist: number;
    maxWaitlist: number;
    days: Set<DayOfWeek>;
    specificSection?: string;
}

export interface Time {
    hours: number;
    minutes: number;
    displayTime: string;
}

export enum DayOfWeek {
    MONDAY = 'M',
    TUESDAY = 'T',
    WEDNESDAY = 'W',
    THURSDAY = 'R',
    FRIDAY = 'F',
    SATURDAY = 'S',
    SUNDAY = 'U'
}

export interface ScheduleDB {
    departments: Department[];
    generated: string;
}

export interface PlannerState {
    courses: Course[];
    selectedYear: number;
    searchTerm: string;
    activeFilters: string[];
    plan: {
        [year: number]: {
            fall: Course[];
            spring: Course[];
            summer: Course[];
        };
    };
}

export type Semester = 'fall' | 'spring' | 'summer';